import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.BfI5QxtK.js";const u=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"testing.md","filePath":"testing.md"}'),n={name:"testing.md"};function o(r,e,d,l,p,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>Use a focused test while editing. Run the broader checks before a release.</p><h2 id="choose-a-check" tabindex="-1">Choose a check <a class="header-anchor" href="#choose-a-check" aria-label="Permalink to &quot;Choose a check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Checks</th><th>Requires</th></tr></thead><tbody><tr><td><code>just check</code></td><td>Syntax, logic, config parser and script tests</td><td>Test dependencies</td></tr><tr><td><code>just test-session</code></td><td>All isolated Shell integration tests</td><td>Current local build</td></tr><tr><td><code>just test-all</code></td><td>Fast checks, fresh build, headless integration</td><td>Build dependencies</td></tr><tr><td><code>just test-window-manager</code></td><td>Mutter native/Wayland/focus suites</td><td>Working seat and file monitoring</td></tr><tr><td><code>just test-release</code></td><td>Full checks plus native tests and RPM builds</td><td>Real host and packaging tools</td></tr></tbody></table><p>A passing headless build does not prove login, visible shell controls or portal consent. Use <a href="./real-hardware-verification">hardware verification</a> for those.</p><h2 id="focused-integration-checks" tabindex="-1">Focused integration checks <a class="header-anchor" href="#focused-integration-checks" aria-label="Permalink to &quot;Focused integration checks&quot;">​</a></h2><p>Run against the prefix built from your current source:</p><table tabindex="0"><thead><tr><th>Command</th><th>Covers</th></tr></thead><tbody><tr><td><code>just test-startup</code></td><td>Gnoblin startup and protocol advertisement</td></tr><tr><td><code>just test-stock-gnome</code></td><td>Stock GNOME behavior stays separate</td></tr><tr><td><code>just test-protocols</code></td><td>Wayland object and geometry contracts</td></tr><tr><td><code>just test-control-api</code></td><td>Control API</td></tr><tr><td><code>just test-preview</code></td><td>Devkit environment and connectivity</td></tr><tr><td><code>just fuzz-lifecycle</code></td><td>Seeded window and frame lifecycle stress</td></tr><tr><td><code>just test-native-chrome</code></td><td>Removed native UI stays absent</td></tr><tr><td><code>just test-scripting</code></td><td>User script load/reload lifecycle</td></tr><tr><td><code>just test-notifications</code></td><td>Notification service ownership</td></tr><tr><td><code>just test-protocol-gating</code></td><td>Startup protocol switches</td></tr></tbody></table><h2 id="run-a-private-test" tabindex="-1">Run a private test <a class="header-anchor" href="#run-a-private-test" aria-label="Permalink to &quot;Run a private test&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_TEST_DBUS_CLIENT=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tests/test-permissions-live.py&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bash </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">scripts/run-gnome-shell.sh</span></span></code></pre></div><p>Choose the test matching your change. Tests live in <code>tests/</code>; build and launch helpers live in <code>scripts/</code>.</p><p>The private harness uses temporary HOME and XDG directories. The <a href="./devkit#isolation">devkit</a> keeps the real HOME; do not confuse the two.</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p>The verification workflow provisions disposable Fedora and Arch images, then runs <code>./build.sh</code> as an unprivileged user. Package provisioning is confined to the CI images; the user-facing build script never runs it.</p><p>A separate matrix checks dependency provisioning and build tests on Debian, Ubuntu and openSUSE. It does not prove a complete desktop installation. Run <code>python3 tests/build-deps.test.py</code> and <code>python3 tests/private-deps.test.py</code> to check command planning, checksums and private library links.</p><p>Graphical login and interactive checks still need a host.</p><h2 id="window-lifecycle-fuzzing" tabindex="-1">Window lifecycle fuzzing <a class="header-anchor" href="#window-lifecycle-fuzzing" aria-label="Permalink to &quot;Window lifecycle fuzzing&quot;">​</a></h2><p><code>just fuzz-lifecycle</code> runs a seeded state-machine fuzzer in a private headless Gnoblin session. It opens real GTK Wayland windows, enables native Gnoblin frames, then mixes pointer crossing/click/resize, window state changes, and graceful, compositor-requested, and abrupt client closes.</p><p>Every run finishes by exiting Gnoblin while a native frame is under the pointer. The run fails if the shell stops responding unexpectedly or logs a fatal compositor diagnostic.</p><p>Use <code>just fuzz-lifecycle SEED=1738 STEPS=1000</code> to control a run. Every run keeps its seed, action plan, executed action prefix, runner output, and shell log under <code>$XDG_STATE_HOME/gnoblin/lifecycle-fuzz/</code> (normally <code>~/.local/state/gnoblin/lifecycle-fuzz/</code>). Replay a failure with the command printed by the runner, or run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/window-lifecycle-fuzz.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --replay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/repro.json</span></span></code></pre></div><p>The harness reports failures and prepares a repair request alongside the exact replay. A generated patch still needs to pass that replay and the relevant compositor checks before it is accepted.</p><h2 id="broad-application-e2e" tabindex="-1">Broad application E2E <a class="header-anchor" href="#broad-application-e2e" aria-label="Permalink to &quot;Broad application E2E&quot;">​</a></h2><p><code>.github/workflows/application-e2e.yml</code> is the app-compatibility workflow; <code>.github/workflows/compositor-fuzz.yml</code> is the separate seeded state-machine workflow. The fuzz workflow runs for pull requests, pushes to <code>main</code>, nightly, and manual dispatch. The app sweep runs one shard on a pull request, all shards weekly, or a selected/full set on manual dispatch.</p><p>At workflow start, <code>tests/e2e/app-catalog.py</code> refreshes two independent sources:</p><ul><li>The first 500 unique desktop apps in Flathub&#39;s Popular collection.</li><li>300 launchable Fedora RPM applications from <code>appstream-data</code>, balanced over the metadata categories and excluding duplicate desktop IDs from Flathub.</li></ul><p>That makes an 800-application catalog without committing a stale popularity snapshot. The workflow divides it into 40 shards. Each app is installed or its installation failure is recorded, then launched in a disposable user session on the built Gnoblin Mutter compositor.</p><p>A real <code>zwlr-layer-shell</code> panel stays mapped for the duration. The driver records whether each app maps a window, then captures a screenshot and checks activation, native frames, move/resize, titlebar dragging, resize handles, maximize, minimize, fullscreen and close. It also saves the app&#39;s stdout and stderr.</p><p>A shard fails if an app cannot be installed or mapped, a supported window operation is rejected, a window cannot close, or the compositor fails. The artifacts distinguish those outcomes.</p><p>Flathub apps keep their Flatpak sandbox and run without network access, so this suite measures desktop-window behavior rather than online service behavior.</p><p>The Actions runner uses Fedora 44 and Gnoblin&#39;s actual Mutter/Wayland code with virtual 1280x800 monitors and software rendering. It exercises real Flatpak and RPM clients against real Gnoblin windows without a physical GPU or logged-in desktop.</p><p>GPU drivers, physical input devices and a hardware login need separate coverage using the <a href="./real-hardware-verification">hardware verification</a> checklist.</p><p>Each shard artifact contains its exact catalog slice, installation report, per-app logs and screenshots, JSONL operation trace, summary, shell log and a reproduction/repair request when it fails. Re-run a shard locally after installing its recorded apps with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_E2E_CATALOG=/path/to/app-catalog.json </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_E2E_SHARD_INDEX=0 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">GNOBLIN_E2E_SHARD_COUNT=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">python3 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tests/e2e/app-e2e.py</span></span></code></pre></div><p>The test workflows produce machine-readable repair packets and exact replays. Source patching still needs a configured repair worker that can run the replay, check the fix and open a reviewable change.</p><h2 id="environment-failures" tabindex="-1">Environment failures <a class="header-anchor" href="#environment-failures" aria-label="Permalink to &quot;Environment failures&quot;">​</a></h2><p>Mutter backend tests need a seat and working local file monitoring. If they fail with <code>Unable to find default local file monitor type</code> (exit 251), fix that environment before treating the run as compositor evidence.</p><h2 id="add-a-test" tabindex="-1">Add a test <a class="header-anchor" href="#add-a-test" aria-label="Permalink to &quot;Add a test&quot;">​</a></h2><p>Use an existing <code>tests/test-*.sh</code> as a starting point. Assert observable behavior, keep session state private, and preserve literal errors. Add an appropriate Just recipe and include it in the relevant suite.</p>`,39)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
